import sys

sys.setrecursionlimit(100000)

DIV0 = "#DIV/0!"
CYCLE = "#CYCLE!"


def _tokenize(s: str):
    toks = []
    i, n = 0, len(s)
    two = {"<=", ">=", "<>"}
    while i < n:
        ch = s[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            toks.append(("num", int(s[i:j])))
            i = j
        elif ch.isalpha():
            j = i
            while j < n and s[j].isalpha():
                j += 1
            letters = s[i:j]
            k = j
            while k < n and s[k].isdigit():
                k += 1
            if k > j and len(letters) == 1:
                toks.append(("cell", letters + s[j:k]))
            else:
                toks.append(("name", letters))
                k = j
            i = k
        elif s[i:i + 2] in two:
            toks.append(("op", s[i:i + 2]))
            i += 2
        elif ch in "+-*/=<>":
            toks.append(("op", ch))
            i += 1
        elif ch == "(":
            toks.append(("lparen", "("))
            i += 1
        elif ch == ")":
            toks.append(("rparen", ")"))
            i += 1
        elif ch == ",":
            toks.append(("comma", ","))
            i += 1
        elif ch == ":":
            toks.append(("colon", ":"))
            i += 1
    return toks


def _parse_formula(s: str):
    toks = _tokenize(s)
    p = [0]

    def peek(off=0):
        i = p[0] + off
        return toks[i] if i < len(toks) else (None, None)

    def eat():
        t = toks[p[0]]
        p[0] += 1
        return t

    def parse_add():
        node = parse_mul()
        while True:
            k, v = peek()
            if k == "op" and v in "+-":
                eat()
                node = ("bin", v, node, parse_mul())
            else:
                return node

    def parse_mul():
        node = parse_unary()
        while True:
            k, v = peek()
            if k == "op" and v in "*/":
                eat()
                node = ("bin", v, node, parse_unary())
            else:
                return node

    def parse_unary():
        k, v = peek()
        if k == "op" and v == "-":
            eat()
            return ("neg", parse_unary())
        return parse_atom()

    def parse_atom():
        k, v = peek()
        if k == "num":
            eat()
            return ("num", v)
        if k == "cell":
            eat()
            return ("cell", v)
        if k == "lparen":
            eat()
            node = parse_add()
            assert peek()[0] == "rparen"
            eat()
            return node
        if k == "name":
            eat()
            assert peek()[0] == "lparen"
            eat()
            if v == "IF":
                left = parse_add()
                k2, op = peek()
                assert k2 == "op"
                eat()
                right = parse_add()
                assert peek()[0] == "comma"
                eat()
                then = parse_add()
                assert peek()[0] == "comma"
                eat()
                els = parse_add()
                assert peek()[0] == "rparen"
                eat()
                return ("if", op, left, right, then, els)
            args = []
            while True:
                if peek()[0] == "cell" and peek(1)[0] == "colon":
                    c1 = eat()[1]
                    eat()
                    assert peek()[0] == "cell"
                    c2 = eat()[1]
                    args.append(("range", c1, c2))
                else:
                    args.append(parse_add())
                k2 = peek()[0]
                if k2 == "comma":
                    eat()
                    continue
                assert k2 == "rparen"
                eat()
                break
            return ("call", v, args)
        raise ValueError("unexpected token")

    return parse_add()


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    asts = {}
    for name, content in cells.items():
        s = content.strip()
        if s.startswith("="):
            asts[name] = _parse_formula(s[1:])
        else:
            asts[name] = ("num", int(s))

    memo = {}
    visiting = set()

    def get(name):
        if name in memo:
            return memo[name]
        if name not in asts:
            return 0
        if name in visiting:
            return CYCLE
        visiting.add(name)
        val = ev(asts[name])
        visiting.discard(name)
        memo[name] = val
        return val

    def ev(node):
        tag = node[0]
        if tag == "num":
            return node[1]
        if tag == "cell":
            return get(node[1])
        if tag == "neg":
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if tag == "bin":
            _, op, l, r = node
            lv = ev(l)
            if isinstance(lv, str):
                return lv
            rv = ev(r)
            if isinstance(rv, str):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            if rv == 0:
                return DIV0
            q = abs(lv) // abs(rv)
            return -q if (lv < 0) != (rv < 0) else q
        if tag == "if":
            _, op, l, r, t, e = node
            lv = ev(l)
            if isinstance(lv, str):
                return lv
            rv = ev(r)
            if isinstance(rv, str):
                return rv
            if op == "=":
                cond = lv == rv
            elif op == "<>":
                cond = lv != rv
            elif op == "<":
                cond = lv < rv
            elif op == "<=":
                cond = lv <= rv
            elif op == ">":
                cond = lv > rv
            else:
                cond = lv >= rv
            return ev(t if cond else e)
        _, fn, args = node
        total = 0
        best = None
        for arg in args:
            if arg[0] == "range":
                c1, r1 = arg[1][0], int(arg[1][1:])
                c2, r2 = arg[2][0], int(arg[2][1:])
                lo_c, hi_c = sorted((ord(c1) - 65, ord(c2) - 65))
                lo_r, hi_r = sorted((r1, r2))
                for row in range(lo_r, hi_r + 1):
                    for col in range(lo_c, hi_c + 1):
                        nm = chr(65 + col) + str(row)
                        if nm not in cells:
                            continue
                        v = get(nm)
                        if isinstance(v, str):
                            return v
                        if fn == "SUM":
                            total += v
                        elif fn == "MIN":
                            best = v if best is None else min(best, v)
                        else:
                            best = v if best is None else max(best, v)
            else:
                v = ev(arg)
                if isinstance(v, str):
                    return v
                if fn == "SUM":
                    total += v
                elif fn == "MIN":
                    best = v if best is None else min(best, v)
                else:
                    best = v if best is None else max(best, v)
        if fn == "SUM":
            return total
        return 0 if best is None else best

    return {name: get(name) for name in cells}
